using System;
using System.Collections.Generic;

namespace GloomhavenVR.Core;

/// <summary>
/// Player-facing VR settings help, separate from config-file diagnostics and implementation notes.
/// Exact entries take precedence over the existing bounded hand/board/pile families. Tables are
/// created only when help is first requested; lookups do not run as part of the frame loop.
/// </summary>
internal static partial class Loc
{
    private static Dictionary<string, Dictionary<string, string>>? _playerConfigHelp;
    private static Dictionary<string, Dictionary<string, string>>? _playerModHelp;

    internal static string? ConfigHelpForPlayers(string section, string key)
    {
        if (string.IsNullOrEmpty(section) || string.IsNullOrEmpty(key)) return null;
        var table = _playerConfigHelp ??= BuildPlayerConfigHelp();
        string address = section + "/" + key;
        if (!table.TryGetValue(address, out var value))
        {
            string? family = FamilyKey(key);
            if (family == null || !table.TryGetValue(section + "/" + family, out value)) return null;
        }
        return PlayerHelpLanguage(value);
    }

    internal static string? ModHelpForPlayers(string hintKey)
    {
        if (string.IsNullOrEmpty(hintKey)) return null;
        var table = _playerModHelp ??= BuildPlayerModHelp();
        return table.TryGetValue(hintKey, out var value) ? PlayerHelpLanguage(value) : null;
    }

    private static string PlayerHelpLanguage(Dictionary<string, string> value) =>
        value.TryGetValue(CurrentLanguage, out var translated) ? translated : value["English"];

