            ["Hands/CurlProximal"] = Pair("Finger-knuckle bend at full grip, in degrees.", "Beugung der Fingergrundgelenke bei vollem Griff in Grad."),
            ["Hands/CurlTip"] = Pair("Fingertip-joint bend at full grip, in degrees.", "Beugung der Fingerspitzengelenke bei vollem Griff in Grad."),
            ["Hands/GhostHandOnFan"] = Pair("Make the hand partly transparent while its card fan is open.", "Macht die Hand bei geöffnetem Kartenfächer teilweise transparent."),
            ["Hands/GhostHandOnHeldCard"] = Pair("Make a hand partly transparent while it holds a card, so the fingers obscure less artwork.", "Macht eine Hand beim Halten einer Karte teilweise transparent, damit die Finger weniger Karteninhalt verdecken."),
            ["Hands/GhostHandStrength"] = Pair("Hand transparency while holding a card or displaying the fan. Higher values make the hand more transparent.", "Transparenz der Hand beim Kartenhalten oder geöffneten Fächer. Höhere Werte machen die Hand durchsichtiger."),
            ["Hands/GloveGripRollDegrees"] = Pair("Sideways tilt of this hand style, in degrees; mirrored between hands.", "Seitliche Neigung dieses Handstils in Grad; zwischen den Händen gespiegelt."),
            ["Hands/GloveGripYawDegrees"] = Pair("Left/right rotation of this hand style, in degrees; mirrored between hands.", "Links-Rechts-Drehung dieses Handstils in Grad; zwischen den Händen gespiegelt."),
            ["Hands/GlovePinkyCounterAbduction"] = Pair("Move the curled glove's little finger toward the ring finger. 0 removes this adjustment.", "Bewegt den gekrümmten kleinen Finger des Handschuhs zum Ringfinger. 0 entfernt diese Anpassung."),
            ["Hands/GloveSpreadOffset"] = Pair("Sideways separation of the hands, in meters. Positive values move them farther apart.", "Seitlicher Abstand der Hände in Metern. Positive Werte bewegen sie weiter auseinander."),
            ["Hands/HandColor"] = Pair("Base color of fallback hands, as six hexadecimal color digits without #.", "Grundfarbe der Ersatzhände als sechs hexadezimale Farbzeichen ohne #."),
            ["Hands/HandStyle"] = Pair("Choose the appearance of your hands. Other VR players see the same hand style.", "Wählt das Aussehen deiner Hände. Andere VR-Spieler sehen denselben Handstil."),
            ["Hands/LaserFingerOffsetMeters"] = Pair("Offset of the visible laser's origin from the index fingertip, in meters.", "Versatz des sichtbaren Laserursprungs von der Zeigefingerspitze in Metern."),
            ["Hands/LaserFingerOrigin"] = Pair("Start the visible laser at your index fingertip instead of the controller.", "Lässt den sichtbaren Laser an deiner Zeigefingerspitze statt am Controller beginnen."),
            ["Hands/PlateGripRollDegrees"] = Pair("Sideways tilt of this hand style, in degrees; mirrored between hands.", "Seitliche Neigung dieses Handstils in Grad; zwischen den Händen gespiegelt."),
            ["Hands/PlateGripYawDegrees"] = Pair("Left/right rotation of this hand style, in degrees; mirrored between hands.", "Links-Rechts-Drehung dieses Handstils in Grad; zwischen den Händen gespiegelt."),
            ["Hands/PlateSpreadOffset"] = Pair("Sideways separation of the hands, in meters. Positive values move them farther apart.", "Seitlicher Abstand der Hände in Metern. Positive Werte bewegen sie weiter auseinander."),
            ["Hands/PrimaryHand"] = Pair("Choose your main controller for laser pointing and primary actions.", "Wählt deinen Hauptcontroller für Laserziele und Hauptaktionen."),
            ["Hands/ScrollWithStickOnly"] = Pair("Scroll lists with the stick instead of dragging them with the laser. Sliders and scrollbars remain draggable.", "Scrollt Listen mit dem Stick statt durch Laserziehen. Schieberegler und Scrollbalken bleiben ziehbar."),
            ["Hands/TestFist"] = Pair("Force both hands into a full fist to check finger alignment.", "Erzwingt an beiden Händen eine volle Faust zur Prüfung der Fingerausrichtung."),
            ["Haunt/EasterEggs"] = Pair("Show occasional atmospheric apparitions in the cellar and forest, away from the board.", "Zeigt gelegentliche atmosphärische Erscheinungen im Keller und Wald, außerhalb des Spielbretts."),
            ["Haunt/Frequency"] = Pair("How often atmospheric apparitions occur. Higher values show more events.", "Häufigkeit atmosphärischer Erscheinungen. Höhere Werte zeigen mehr Ereignisse."),
            ["HexHighlight/LogMaterialDump"] = Pair("Record tile-highlight material details in the log for troubleshooting visual problems.", "Protokolliert Materialdetails der Feldhervorhebung zur Untersuchung von Darstellungsproblemen."),
            ["Keyboard/AutoCapitalise"] = Pair("Start entered names with a capital letter automatically.", "Beginnt eingegebene Namen automatisch mit einem Großbuchstaben."),
            ["Lights/FlickerDamping"] = Pair("Reduce abrupt light-intensity fluctuations.", "Dämpft abrupte Schwankungen der Lichtstärke."),
            ["Lights/PinnedPixelLights"] = Pair("Number of full-quality lights retained by the lighting stabilizer.", "Anzahl vollständig berechneter Lichter, die die Beleuchtungsstabilisierung erhält."),
            ["Lights/StabiliseAtZeroCap"] = Pair("Stabilize lighting when the full-quality light limit is zero, reducing visible changes as you look around.", "Stabilisiert die Beleuchtung bei null vollständig berechneten Lichtern und reduziert sichtbare Änderungen beim Umsehen."),
            ["Lights/StabiliserResponseSeconds"] = Pair("Seconds for lighting to settle toward new values. Higher values smooth changes more slowly.", "Sekunden bis zum Einpendeln der Beleuchtung auf neue Werte. Höhere Werte glätten Änderungen langsamer."),
            ["MapRoom/CityIconScale"] = Pair("Size of service markers on the 3D city map.", "Größe der Dienstleistungsmarkierungen auf der 3D-Stadtkarte."),
            ["MapRoom/GloomhavenIconScale"] = Pair("Size of the Gloomhaven city marker.", "Größe der Stadtmarkierung Gloomhaven."),
            ["MapRoom/HoverAnimation"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["MapRoom/IconScale"] = Pair("Size of quest markers on the 3D world map.", "Größe der Questmarkierungen auf der 3D-Weltkarte."),
            ["MapRoom/PartyMarkerScale"] = Pair("Size of your party's map marker.", "Größe der Gruppenmarkierung auf der Karte."),
            ["MapRoom/PathWidthScale"] = Pair("Width of travel paths on the 3D map.", "Breite der Reisewege auf der 3D-Karte."),
            ["MixedReality/Enabled"] = Pair("Replace the surroundings with a solid chroma-key color for compatible streaming passthrough software.", "Ersetzt die Umgebung durch eine Chroma-Key-Farbe für kompatible Passthrough-Streamingsoftware."),
            ["MixedReality/HideSkyMeshes"] = Pair("Hide sky and background geometry while mixed reality is enabled.", "Blendet Himmel- und Hintergrundgeometrie bei aktivierter Mixed Reality aus."),
            ["MixedReality/KeyColor"] = Pair("Background color that compatible passthrough software replaces with your real surroundings.", "Hintergrundfarbe, die kompatible Passthrough-Software durch deine reale Umgebung ersetzt."),
            ["MixedReality/OpaquePreviewTiles"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["MixedReality/UnseenBackingDebugColors"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["MixedReality/UnseenRegionMembership"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["MixedReality/UnseenRimInset"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["MixedReality/UnseenRimTopClearance"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["MixedReality/UnseenSkirtScale"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["MixedReality/UnseenWaferDrop"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["Net/DesyncPatienceSeconds"] = Pair("Seconds to wait before reporting an unresolved synchronization mismatch.", "Wartezeit in Sekunden vor der Meldung einer anhaltenden Synchronisierungsabweichung."),
            ["Net/Enabled"] = Pair("Show VR players and synchronize your VR avatar and public presentation with them.", "Zeigt VR-Spieler und synchronisiert deinen VR-Avatar sowie die öffentliche Darstellung mit ihnen."),
            ["Net/MaskId"] = Pair("Choose the head mask other players see on your avatar.", "Wählt die Kopfmaske, die andere Spieler an deinem Avatar sehen."),
            ["Net/MaskSize"] = Pair("Size of your avatar's head mask. Other players see the same size.", "Größe deiner Avatar-Kopfmaske. Andere Spieler sehen dieselbe Größe."),
            ["Net/MirrorEnabled"] = Pair("Show a local mirror to preview your mask and hands.", "Zeigt einen lokalen Spiegel zur Vorschau deiner Maske und Hände."),
            ["Net/NameTags"] = Pair("Show other players' names and avatar pictures above their head masks.", "Zeigt Namen und Avatarbilder anderer Spieler über deren Kopfmasken."),
            ["Net/RemoteBoards"] = Pair("Choose when other players' control boards are visible: never, during actions, or always.", "Wählt, wann Mitspieler-Kontrollbretter sichtbar sind: nie, während Aktionen oder immer."),
            ["Net/VersionGuard"] = Pair("Warn when VR players use incompatible mod builds and offer a connection without VR synchronization.", "Warnt bei inkompatiblen Mod-Versionen und bietet eine Verbindung ohne VR-Synchronisierung an."),
            ["Optimize/ActorBarPoseCheckIntervalSeconds"] = Pair("Seconds between height checks for stationary figures' healthbars. Higher values reduce CPU work; actions still update their height.", "Sekunden zwischen Höhenprüfungen der Lebensbalken ruhender Figuren. Höhere Werte sparen CPU-Arbeit; Aktionen aktualisieren die Höhe weiterhin."),
            ["Optimize/AutomaticLodSweepSeconds"] = Pair("Seconds between checks for redundant automatic-detail update work. Longer intervals delay optimization of newly loaded objects.", "Sekunden zwischen Prüfungen auf überflüssige automatische Detailarbeit. Längere Intervalle verzögern die Optimierung neu geladener Objekte."),
            ["Optimize/FanRelayoutMinInterval"] = Pair("Minimum seconds between gaze-driven fan rearrangements. Higher values reduce work but slow the fan's response.", "Mindestabstand in Sekunden zwischen blickgesteuerten Fächeranpassungen. Höhere Werte sparen Arbeit, machen den Fächer aber träger."),
            ["Optimize/FigureDistanceLod"] = Pair("Reduce scenario figures' body detail with distance. Nearby and held figures retain their selected detail limit.", "Verringert die Körperdetails von Szenariofiguren mit dem Abstand. Nahe und gehaltene Figuren behalten ihre gewählte Detailgrenze."),
            ["Optimize/HeadCullingMaskDrop"] = Pair("Hide selected rendering layers from the VR view. Enter layer names or indices separated by commas; this can hide needed content.", "Blendet ausgewählte Renderebenen in VR aus. Ebenennamen oder Nummern mit Kommas trennen; dies kann benötigte Inhalte verbergen."),
            ["Optimize/HeadDepthPrepass"] = Pair("Generate a depth texture for effects that need scene depth. Turning this off reduces rendering work but may affect those effects.", "Erzeugt eine Tiefentextur für Effekte, die Szenentiefe benötigen. Aus spart Renderarbeit, kann diese Effekte aber beeinträchtigen."),
            ["Optimize/HeadMaskFromScenarioCamera"] = Pair("Use the scenario camera's rendering layers for VR during scenarios. Affects which objects are visible.", "Nutzt im Szenario die Renderebenen der Szenariokamera für VR. Beeinflusst, welche Objekte sichtbar sind."),
            ["Optimize/InitiativeDepthEvalInterval"] = Pair("Minimum seconds between depth adjustments of the initiative row. Higher values reduce update work.", "Mindestabstand in Sekunden zwischen Tiefenanpassungen der Initiativreihe. Höhere Werte sparen Aktualisierungsarbeit."),
            ["Optimize/LodBias"] = Pair("Distance-detail bias. Higher values retain more detailed models farther away; lower values favor simpler models.", "Gewichtung der Entfernungsdetails. Höhere Werte halten detaillierte Modelle länger sichtbar; kleinere bevorzugen einfachere Modelle."),
            ["Optimize/OffscreenIdleAnimation"] = Pair("Reduce idle-animation work for figures outside your view. Figures performing actions remain animated.", "Reduziert die Berechnung von Ruheanimationen außerhalb deines Blickfelds. Figuren mit Aktionen bleiben animiert."),
            ["Optimize/QuietDiagnostics"] = Pair("Reduce repetitive diagnostic log entries. Important failures remain recorded.", "Reduziert wiederholte Diagnoseeinträge im Log. Wichtige Fehler werden weiterhin protokolliert."),
            ["Optimize/ReduceScenarioGenerationDetail"] = Pair("Use the game's simpler procedural geometry on the next scenario load. Existing scenarios are not rebuilt.", "Nutzt beim nächsten Szenarioladen die einfachere prozedurale Geometrie des Spiels. Laufende Szenarien werden nicht neu aufgebaut."),
            ["Optimize/RemoteContentInterval"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["Optimize/ScenarioDecorationDensityPercent"] = Pair("Amount of optional scenario decoration. Lower values remove decorative objects while preserving gameplay obstacles.", "Anteil optionaler Szenariodekoration. Kleinere Werte entfernen Zierobjekte; Spielhindernisse bleiben bestehen."),
            ["Optimize/ScenarioEnemyFigureDetailPercent"] = Pair("Body detail of enemies. Lower values use simpler meshes where available; animation and gameplay remain.", "Körperdetails der Gegner. Kleinere Werte nutzen einfachere Meshes, soweit verfügbar; Animation und Spielverhalten bleiben erhalten."),
            ["Optimize/ScenarioEnvironmentMeshBank"] = Pair("Allow static scenery to be grouped even when its original meshes cannot be read. Uses additional memory and preparation; Off keeps originals.", "Erlaubt das Zusammenfassen statischer Umgebung trotz nicht lesbarer Originalmeshes. Benötigt zusätzlichen Speicher und Vorbereitung; Aus erhält das Original."),
            ["Optimize/ScenarioExplicitEnvironmentInstancing"] = Pair("Draw suitable repeated static scenery together. Every revealed room and its interactions stay available; Off restores individual drawing.", "Zeichnet geeignete wiederholte statische Umgebung gemeinsam. Alle aufgedeckten Räume und ihre Interaktionen bleiben verfügbar; Aus stellt einzelne Zeichenvorgänge wieder her."),
            ["Optimize/ScenarioCheapWallShading"] = Pair("Use cheaper wall shading. Fine lighting and surface detail decrease; original textures and animated wall disappearance remain. Floors keep original shading. Applies when world materials are 0.", "Nutzt sparsamere Wandschattierung. Feine Beleuchtung und Oberflächendetails nehmen ab; Originaltexturen und animierte Wandausblendung bleiben. Böden behalten ihre Originalschattierung. Gilt bei Umgebungsmaterialien 0."),
            ["Optimize/ScenarioTerrainSubstitution"] = Pair("Off keeps original 3D geometry and stops substitute preparation; simpler world materials remain independent. Compare the same loaded view: less CPU preparation may cost more GPU work. Saved detail choices return with On; all rooms remain visible.", "Aus erhält originale 3D-Geometrie und beendet die Ersatzvorbereitung; einfache Umgebungsmaterialien bleiben unabhängig. Dieselbe geladene Ansicht vergleichen: weniger CPU-Vorbereitung kann mehr GPU-Arbeit kosten. Ein nutzt wieder gespeicherte Detailwerte; alle Räume bleiben sichtbar."),
            ["Optimize/WorldMaterialQualityModeCount"] = Pair("Static scenery in game and DLCs: 0 keeps original materials plus floor/wall options, 1 uses simple lighting, 2 uses textured color with adjustable ambient light. 1/2 remove relief/gloss; geometry, textures and visibility remain. Works live; unsupported materials stay original.", "Statische Umgebung in Spiel und DLCs: 0 Original mit Boden-/Wandoptionen, 1 einfache Beleuchtung, 2 texturierte Farbe mit einstellbarem Umgebungslicht. 1/2 ohne Relief/Glanz; Geometrie, Texturen und Sichtbarkeit bleiben. Wirkt sofort; ungeeignete Materialien bleiben original."),
            ["Optimize/WorldMaterialAmbientPercent"] = Pair("Ambient lighting in world material mode 2: 100 retains scene atmosphere with original ambient light; 0 shows raw textured color. Values between blend both. Fine surface lighting stays omitted. Works live on all platforms; modes 0/1 are unchanged.", "Umgebungslicht in Materialmodus 2: 100 erhält die Atmosphäre mit ursprünglichem Umgebungslicht; 0 zeigt rohe Texturfarben. Zwischenwerte mischen beides. Feine Oberflächenbeleuchtung bleibt aus. Wirkt sofort auf allen Plattformen; Modi 0/1 bleiben unverändert."),
            ["Optimize/ScenarioTerrainDetailPercent"] = Pair("100% keeps original eligible walls and pillars; lower values select prepared coarser 3D meshes. Floors, doors, figures and game collision remain.", "100% erhält geeignete Originalwände und Säulen; kleinere Werte wählen vorbereitete gröbere 3D-Meshes. Böden, Türen, Figuren und Spielkollisionen bleiben."),
            ["Optimize/ScenarioDistantTerrainDetailPercent"] = Pair("Additional detail cap for eligible walls and pillars at the selected viewing distance. All revealed tactical contents stay represented.", "Zusätzliche Detailgrenze für geeignete Wände und Säulen ab dem gewählten Betrachtungsabstand. Alle aufgedeckten spielrelevanten Inhalte bleiben dargestellt."),
            ["Optimize/ScenarioTerrainDistanceMeters"] = Pair("VR viewing distance at which the distant wall and pillar detail cap applies.", "Betrachtungsabstand in VR, ab dem die Detailgrenze für entfernte Wände und Säulen gilt."),
            ["Optimize/ScenarioTerrainCameraSourceLimitCount"] = Pair("Limit simplified 3D wall/pillar surfaces per eye. 0 is unlimited. Lower positive limits save substitute CPU work; remaining surfaces keep original 3D geometry and shading, which can cost more to render. No room is hidden.", "Begrenzt vereinfachte 3D-Wand- und Säulenflächen pro Auge. 0 ist unbegrenzt. Kleinere positive Werte sparen CPU-Arbeit für Ersatzflächen; übrige Flächen behalten ihre originale 3D-Geometrie und Schattierung und können mehr Renderleistung kosten. Kein Raum wird ausgeblendet."),
            ["Optimize/SharedUiWindowReads"] = Pair("Save repeated native window-registry reads and immediate original-property reads in multiplayer mirrors. Contents, native visibility and animation remain immediate; Off permits a comparison.", "Spart wiederholte Fensterabfragen und unmittelbare Originalabfragen in Multiplayer-Spiegeln. Inhalte, native Sichtbarkeit und Animation bleiben unmittelbar; Aus ermöglicht einen Vergleich."),
            ["Optimize/ScenarioEnvironmentEffectsDensityPercent"] = Pair("Amount of decorative scenery effects, such as moths and flames. Light sources and gameplay effects remain.", "Anteil dekorativer Umgebungseffekte, etwa Motten und Flammen. Lichtquellen und spielrelevante Effekte bleiben erhalten."),
            ["Optimize/ScenarioFigureClothSimulation"] = Pair("Animate figure clothing with cloth physics. Turning this off reduces CPU work and keeps clothing static relative to the animated body.", "Simuliert Figurenkleidung mit Stoffphysik. Aus spart CPU-Arbeit und hält den Stoff relativ zum animierten Körper statisch."),
            ["Optimize/ScenarioFigureEffectsDensityPercent"] = Pair("Amount of decorative figure effects. 0% hides eligible particles, trails and glow surfaces; attacks and status indicators remain.", "Anteil dekorativer Figureneffekte. 0% entfernt geeignete Partikel, Spuren und Leuchtflächen; Angriffe und Zustandsanzeigen bleiben erhalten."),
            ["Optimize/ScenarioPlayerFigureDetailPercent"] = Pair("Body detail of player figures. Lower values use simpler meshes where available; animation and gameplay remain.", "Körperdetails der Spielfiguren. Kleinere Werte nutzen einfachere Meshes, soweit verfügbar; Animation und Spielverhalten bleiben erhalten."),
            ["Optimize/ScenarioSceneryDensityPercent"] = Pair("Amount of decorative grass. 0% hides eligible grass; 100% keeps it. Gameplay obstacles remain.", "Anteil dekorativen Grases. 0% blendet geeignetes Gras aus, 100% erhält es. Spielhindernisse bleiben bestehen."),
            ["Optimize/ScenarioSimpleEnvironmentShading"] = Pair("Simplify eligible opaque floors and static masonry to reduce rendering work. Surface and shadow detail can decrease; fading walls keep their original shading. Applies when world materials are 0.", "Vereinfacht geeignete undurchsichtige Böden und statisches Mauerwerk, um Renderarbeit zu sparen. Oberflächen- und Schattendetails können abnehmen; ausblendbare Wände behalten ihre ursprüngliche Schattierung. Gilt bei Umgebungsmaterialien 0."),
            ["Optimize/ScenarioStaticBatching"] = Pair("Group suitable static floors for drawing. Reduces drawing overhead at the cost of additional preparation.", "Fasst geeignete statische Böden zum Zeichnen zusammen. Spart Zeichenaufwand und benötigt zusätzliche Vorbereitung."),
            ["Optimize/ScenarioStructuralBatching"] = Pair("Group suitable static scenery for drawing. Requires simpler environment shading; grouping takes extra preparation time.", "Fasst geeignete statische Umgebung zum Zeichnen zusammen. Erfordert einfachere Umgebungsschattierung und zusätzliche Vorbereitungszeit."),
            ["Optimize/ScenarioStructuralInstancing"] = Pair("Draw suitable repeated scenery together to reduce rendering work. Unsupported objects keep their normal appearance.", "Zeichnet geeignete wiederholte Umgebung gemeinsam, um Renderarbeit zu sparen. Nicht unterstützte Objekte behalten ihre normale Darstellung."),
            ["Optimize/ScenarioVegetationDensityPercent"] = Pair("Amount of decorative trees, bushes, vines and leaves. 0% hides eligible vegetation; gameplay obstacles remain.", "Anteil dekorativer Bäume, Büsche, Ranken und Blätter. 0% blendet geeignete Vegetation aus; Spielhindernisse bleiben bestehen."),
            ["Optimize/SkinningBoneLimit"] = Pair("Maximum bone influences per vertex: 0 uses game quality; 1, 2 or 4 reduce animation work but may simplify joints.", "Maximale Knocheneinflüsse je Vertex: 0 nutzt die Spielqualität; 1, 2 oder 4 sparen Animationsarbeit, können Gelenke aber vereinfachen."),
            ["Optimize/TownNpcDetailPercent"] = Pair("Stored compatibility value; changing it has no effect.", "Gespeicherter Kompatibilitätswert; Änderungen haben keine Wirkung."),
            ["Optimize/UiMaintenanceIntervalSeconds"] = Pair("Seconds between updates of unchanged windows. Higher values reduce CPU work; visible changes and interaction remain immediate.", "Sekunden zwischen Aktualisierungen unveränderter Fenster. Höhere Werte sparen CPU-Arbeit; sichtbare Änderungen und Bedienung bleiben unmittelbar."),
            ["Optimize/WallFadeEvalInterval"] = Pair("Minimum seconds between wall-visibility checks. Higher values reduce CPU work but delay wall fading.", "Mindestabstand in Sekunden zwischen Wand-Sichtbarkeitsprüfungen. Höhere Werte sparen CPU-Arbeit, verzögern aber die Wanddurchsicht."),
            ["PeerBoardFade/DwellsMigrated312"] = Pair("Internal settings-migration marker; leave unchanged.", "Interner Marker für die Einstellungsübernahme; unverändert lassen."),
            ["PeerBoardFade/ExitDwellMovedSeconds"] = Pair("Seconds before restoring a remote board after you move your view away.", "Sekunden bis zum Wiederherstellen eines Mitspieler-Bretts nach einer Blickbewegung."),
            ["PeerBoardFade/ExitDwellStationarySeconds"] = Pair("Seconds before restoring a remote board while your view stays still.", "Sekunden bis zum Wiederherstellen eines Mitspieler-Bretts bei ruhigem Blick."),
            ["PeerBoardFade/Mode"] = Pair("Choose when another player's board becomes transparent: never, while obstructing your view, or permanently.", "Wählt, wann ein Mitspieler-Brett transparent wird: nie, bei Sichtverdeckung oder dauerhaft."),
            ["PeerBoardFade/OccludedAlpha"] = Pair("Opacity of a transparent remote board. Lower values make it easier to see through.", "Deckkraft eines transparenten Mitspieler-Bretts. Kleinere Werte machen es durchsichtiger."),
            ["PeerBoardFade/OffFraction"] = Pair("Obstructed fraction below which a remote board becomes opaque again.", "Verdeckter Anteil, unter dem ein Mitspieler-Brett wieder undurchsichtig wird."),
            ["PeerBoardFade/OnFraction"] = Pair("Fraction of your view that a remote board must obstruct before it becomes transparent.", "Anteil deiner Sicht, den ein Mitspieler-Brett verdecken muss, bevor es transparent wird."),
            ["Perf/Allocations"] = Pair("Include memory-allocation and garbage-collection measurements in performance reports.", "Ergänzt Leistungsberichte um Speicherbelegungs- und Speicherbereinigungsmessungen."),
            ["Perf/Attribution"] = Pair("Measure individual VR processing steps to help locate performance bottlenecks.", "Misst einzelne VR-Arbeitsschritte, um Leistungsengpässe einzugrenzen."),
            ["Perf/CullSubmitSplit"] = Pair("Measure visibility determination and drawing submission separately per camera.", "Misst Sichtbarkeitsbestimmung und Zeichenabgabe getrennt je Kamera."),
            ["Perf/Enabled"] = Pair("Record frame-time measurements in the log to help investigate stuttering. Measurement adds some overhead.", "Zeichnet Bildzeiten im Log auf, um Ruckler zu untersuchen. Die Messung verursacht zusätzlichen Aufwand."),
            ["Perf/FrameSplit"] = Pair("Separate CPU processing, rendering and runtime waiting in performance reports.", "Schlüsselt Leistungsberichte nach CPU-Arbeit, Rendering und Wartezeiten auf."),
            ["Perf/LodCensus"] = Pair("Include figure detail-level counts in performance reports.", "Ergänzt Leistungsberichte um die Anzahl der Figuren je Detailstufe."),
            ["Perf/ProfileDefaultsMigrated227"] = Pair("Internal settings-migration marker; leave unchanged.", "Interner Marker für die Einstellungsübernahme; unverändert lassen."),
            ["Perf/SceneCensus"] = Pair("Count active and visible renderers in performance reports.", "Zählt aktive und sichtbare Renderobjekte in Leistungsberichten."),
            ["Perf/SceneProfile"] = Pair("Add a detailed scene inventory to Debug logs. This adds measurement work.", "Ergänzt Debug-Logs um eine detaillierte Szenenübersicht. Die Erfassung verursacht zusätzlichen Aufwand."),
            ["Perf/SceneProfileBudgetMilliseconds"] = Pair("Time budget in milliseconds per frame for the detailed scene inventory.", "Zeitbudget in Millisekunden pro Bild für die detaillierte Szenenübersicht."),
            ["Perf/SceneProfileObjectsPerFrame"] = Pair("Maximum inventory steps per frame. Smaller values spread diagnostic work over more frames.", "Maximale Erfassungsschritte pro Bild. Kleinere Werte verteilen die Diagnosearbeit auf mehr Bilder."),
            ["Perf/SpikeBudgetFactor"] = Pair("Report frames that exceed this multiple of the headset's frame-time budget.", "Meldet Bilder, deren Dauer dieses Vielfache des Bildzeitbudgets des Headsets überschreitet."),
            ["Perf/SpikeLines"] = Pair("Log individual slow frames, in addition to regular performance summaries.", "Protokolliert einzelne langsame Bilder zusätzlich zu den regelmäßigen Leistungsübersichten."),
            ["Perf/SpikeMaxPerSecond"] = Pair("Maximum slow-frame log entries per second. Lower values keep the log smaller.", "Maximale Anzahl von Logeinträgen für langsame Bilder pro Sekunde. Kleinere Werte begrenzen die Loggröße."),
            ["Perf/SummaryIntervalSeconds"] = Pair("Seconds between performance summaries in the log. Shorter intervals produce more log entries.", "Sekunden zwischen Leistungsübersichten im Log. Kürzere Intervalle erzeugen mehr Logeinträge."),
            ["Perf/TopSteps"] = Pair("Number of the slowest processing steps included in each performance summary.", "Anzahl der langsamsten Arbeitsschritte in jeder Leistungsübersicht."),
